import{_ as i,a0 as l,w as o,s as r,ao as d,I as p,x as s,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"使用 Flutter 開發簡單的 Web 應用 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Flutter 開發簡單的 Web 應用 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Flutter 開發簡單的 Web 應用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Flutter 開發簡單的 Web 應用 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191115 Developing a Simple Web Application Using Flutter","title":"使用 Flutter 開發簡單的 Web 應用","tag":"201911","desc":""},"relativePath":"201911/20191115 Developing a Simple Web Application Using Flutter.md","filePath":"[post].md"}'),u={name:"201911/20191115 Developing a Simple Web Application Using Flutter.md"};function c(g,e,h,b,f,m){const t=l("Link");return o(),r("div",null,[e[15]||(e[15]=d(`<h1 id="使用-flutter-開發簡單的-web-應用" tabindex="-1">使用 Flutter 開發簡單的 Web 應用 <a class="header-anchor" href="#使用-flutter-開發簡單的-web-應用" aria-label="Permalink to “使用 Flutter 開發簡單的 Web 應用”">​</a></h1><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Screenshot-from-2019-11-15-16-20-30.png" alt=""></p><blockquote><p>本文指導讀者如何使用 Flutter 運行和部署第一個 Web 應用。</p></blockquote><p>Flutter 在 Android 和 iOS 開發方面走了很長一段路之後，已經邁入了一個新的階段，即 Web 開發。Google 發佈了 Flutter 1.5，同時支持 Web 應用開發。</p><h3 id="為-web-開發配置-flutter" tabindex="-1">為 Web 開發配置 Flutter <a class="header-anchor" href="#為-web-開發配置-flutter" aria-label="Permalink to “為 Web 開發配置 Flutter”">​</a></h3><p>為了使用 Web 包，輸入命令 <code>flutter upgrade</code> 更新到 Flutter 1.5.4。</p><ul><li>打開終端</li><li>輸入 <code>flutter upgrade</code></li><li>輸入 <code>flutter –version</code> 檢查版本</li></ul><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-1-Upgrading-Flutter-to-the-latest-version.jpg" alt="圖 1: 升級 Flutter 到最新版"></p><p>也可以將 Android Studio 3.0 或更高版本用於 Flutter Web 開發，但在本教程中，我們使用 Visual Studio Code。</p><h3 id="使用-flutter-web-創建新項目" tabindex="-1">使用 Flutter Web 創建新項目 <a class="header-anchor" href="#使用-flutter-web-創建新項目" aria-label="Permalink to “使用 Flutter Web 創建新項目”">​</a></h3><p>打開 Visual Studio Code，然後按 <code>Shift+Ctrl+P</code> 開始一個新項目。輸入 <code>flutter</code> 並選擇 “New Web Project”。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-2-Starting-a-new-Flutter-Web-project-in-VSC.jpg" alt="圖 2：在 VSC 中開始一個新的 Flatter 項目"></p><p>現在，為項目命名。我將其命名為 <code>open_source_for_you</code>。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-3-Naming-the-project.jpg" alt="圖 3: 給項目命名"></p><p>在 VSC 中打開終端窗口，然後輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flutter packages pub global activate webdev</span></span>
<span class="line"><span>flutter packages upgrade</span></span></code></pre></div><p>現在，使用以下命令在 localhost 上運行網站，IP 地址是 127.0.0.1。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flutter packages pub global run webdev serve</span></span></code></pre></div><p>打開任何瀏覽器，然後輸入 <code>http://127.0.0.1:8080/</code>。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-4-The-Flutter-demo-application-running-on-port-8080.jpg" alt="圖 4：運行於 8080 端口的 Flutter 演示應用"></p><p>在項目目錄中有個 Web 文件夾，其中包含了 <code>index.html</code>。<code>dart</code> 文件被編譯成 JavaScript 文件，並使用以下代碼包含在 HTML 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script defer src=&quot;main.dart.js&quot; type=&quot;application/javascript&quot;&gt;&lt;/script&gt;</span></span></code></pre></div><h3 id="編碼和修改演示頁面" tabindex="-1">編碼和修改演示頁面 <a class="header-anchor" href="#編碼和修改演示頁面" aria-label="Permalink to “編碼和修改演示頁面”">​</a></h3><p>讓我們創建一個簡單的應用，它會在網頁上打印 “Welcome to OSFY”。</p><p>現在打開 Dart 文件，它位於 <code>lib</code> 文件夾 <code>main.dart</code>（默認名）中（參見圖 5）。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-5-Location-of-main.dart-file.jpg" alt="圖 5：main.dart 文件的位置"></p><p>現在，我們可以在 <code>MaterialApp</code> 的屬性中刪除調試標記，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>debugShowCheckedModeBanner: false</span></span></code></pre></div><p>現在，向 Dart 中添加更多內容與用 Dart 編寫 Flutter 很類似。為此，我們可以聲明一個名為 <code>MyClass</code> 的類，它繼承了 <code>StatelessWidget</code>。</p><p>我們使用 <code>Center</code> 部件將元素定位到中心。我們還可以添加 <code>Padding</code> 部件來添加填充。使用以下代碼獲得圖 5 所示的輸出。使用刷新按鈕查看更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class MyClass extends StatelessWidget {</span></span>
<span class="line"><span>  @override</span></span>
<span class="line"><span>  Widget build(BuildContext context) {</span></span>
<span class="line"><span>    return Scaffold(</span></span>
<span class="line"><span>      body: Center(</span></span>
<span class="line"><span>        child: Column(</span></span>
<span class="line"><span>          mainAxisAlignment: MainAxisAlignment.center,</span></span>
<span class="line"><span>          children: &lt;Widget&gt;[</span></span>
<span class="line"><span>            Padding(</span></span>
<span class="line"><span>              padding: EdgeInsets.all(20.0),</span></span>
<span class="line"><span>              child: Text(</span></span>
<span class="line"><span>                &#39;Welcome to OSFY&#39;,</span></span>
<span class="line"><span>                style: TextStyle(fontSize: 24.0, fontWeight: FontWeight.bold),</span></span>
<span class="line"><span>              ),</span></span>
<span class="line"><span>            ),</span></span>
<span class="line"><span>          ],</span></span>
<span class="line"><span>        ),</span></span>
<span class="line"><span>      ),</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-6-Output-of-MyClass.jpg" alt="圖 6：MyClass 的輸出"></p><p>讓我們從互聯網中添加一張圖片，我已經從一個雜誌網站選擇了一張 “Open Source for You” 徽標。我們使用 <code>Image.network</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Image.network(</span></span>
<span class="line"><span>  &#39;https://opensourceforu.com/wp-content/uploads/2014/03/OSFY-Logo.jpg&#39;,</span></span>
<span class="line"><span>  height: 100,</span></span>
<span class="line"><span>  width: 150</span></span>
<span class="line"><span>),</span></span></code></pre></div><p>最終輸出如圖 7 所示。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-7-Final-output.jpg" alt="圖 7：最終輸出"></p><hr>`,37)),p("p",null,[e[1]||(e[1]=s("via: ",-1)),a(t,{href:"https://opensourceforu.com/2019/11/developing-a-simple-web-application-using/"},{default:n(()=>[...e[0]||(e[0]=[s("https://opensourceforu.com/2019/11/developing-a-simple-web-application-using/",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=s("作者：",-1)),a(t,{href:"https://opensourceforu.com/author/jis-joe/"},{default:n(()=>[...e[2]||(e[2]=[s("Jis Joe Mathew",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const w=i(u,[["render",c]]);export{F as __pageData,w as default};
